package e2e_test

import (
	"os/exec"
	"strings"
	"testing"
)

// TestBinaryArtefactsNameTheSameVersion is the shipped-binary half of #1895:
// --version, the man page and all three completions are generated by one
// build and must agree on its version, and the man page's date must come from
// SOURCE_DATE_EPOCH rather than the clock.
func TestBinaryArtefactsNameTheSameVersion(t *testing.T) {
	e := newEnv(t, "{}")

	run := func(extraEnv []string, args ...string) string {
		t.Helper()
		cmd := exec.Command(e.mcpx, args...)
		cmd.Dir = e.dir
		cmd.Env = append(append([]string{}, e.envVars...), extraEnv...)
		out, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("mcpx %s failed: %v\n%s", strings.Join(args, " "), err, out)
		}
		return string(out)
	}

	fields := strings.Fields(strings.TrimSpace(run(nil, "--version")))
	if len(fields) != 2 || fields[0] != "mcpx" {
		t.Fatalf("mcpx --version printed %q; want `mcpx <version>`", strings.TrimSpace(strings.Join(fields, " ")))
	}
	version := fields[1]
	if version == "" {
		t.Fatal("mcpx --version printed an empty version")
	}

	page := run([]string{"SOURCE_DATE_EPOCH=1700000000"}, "man")
	wantHeader := `.TH MCPX 1 "2023-11-14" "mcpx ` + version + `"`
	header, _, _ := strings.Cut(page, "\n")
	// The .TH line continues with the source field ("mcpx manual"); the date
	// and version fields are what must agree with the binary.
	if !strings.HasPrefix(header, wantHeader) {
		t.Errorf("man page header is %q, want prefix %q", header, wantHeader)
	}

	for _, shell := range []string{"bash", "zsh", "fish"} {
		script := run(nil, "completion", shell)
		if strings.TrimSpace(script) == "" {
			t.Errorf("%s completion is empty", shell)
			continue
		}
		if !strings.Contains(script, version) {
			t.Errorf("%s completion does not name version %q", shell, version)
		}
	}
}
